const provider = '__MODEL_PROVIDER__';
const model = '__MODEL_NAME__';
const src = $input.first().json;
const system = src.system || '';
const messages = Array.isArray(src.messages) ? src.messages : [];
const tools = Array.isArray(src.tools) ? src.tools : [];

function sanearParaGemini(schema) {
  const s = JSON.parse(JSON.stringify(schema || {}));
  const walk = (o) => {
    if (!o || typeof o !== 'object') return;
    delete o.additionalProperties;
    delete o.$comment;
    delete o.minLength;
    delete o.minItems;
    if (o.format === 'e164' || o.format === 'uuid') delete o.format;
    if (o.properties) Object.values(o.properties).forEach(walk);
    if (o.items) walk(o.items);
  };
  walk(s);
  return s;
}

let url, method = 'POST', headers = {}, body = {};

if (provider === 'claude') {
  url = 'https://api.anthropic.com/v1/messages';
  headers = { 'anthropic-version': '2023-06-01' };
  body = {
    model,
    max_tokens: 1024,
    temperature: 0.3,
    system,
    messages: messages.map(m => ({
      role: m.role === 'assistant' ? 'assistant' : 'user',
      content: m.content
    })),
    tools: tools.map(t => ({
      name: t.name,
      description: t.description,
      input_schema: t.parameters
    }))
  };
} else {
  url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`;
  headers = {};
  body = {
    system_instruction: { parts: [{ text: system }] },
    contents: messages.map(m => ({
      role: m.role === 'assistant' ? 'model' : 'user',
      parts: typeof m.content === 'string' ? [{ text: m.content }] : m.content
    })),
    tools: [{
      function_declarations: tools.map(t => ({
        name: t.name,
        description: t.description,
        parameters: sanearParaGemini(t.parameters)
      }))
    }],
    generationConfig: { temperature: 0.3 }
  };
}

return [{ json: { url, method, headers, body, provider, model } }];

const provider = '__MODEL_PROVIDER__';
const resp = $input.first().json;
let text = '';
const toolCalls = [];
let usage = { in: 0, out: 0 };

if (provider === 'claude') {
  for (const block of (resp.content || [])) {
    if (block.type === 'text') text += block.text;
    if (block.type === 'tool_use') toolCalls.push({ id: block.id, name: block.name, args: block.input || {} });
  }
  usage = { in: resp.usage?.input_tokens || 0, out: resp.usage?.output_tokens || 0 };
} else {
  const parts = resp.candidates?.[0]?.content?.parts || [];
  for (const p of parts) {
    if (p.text) text += p.text;
    if (p.functionCall) toolCalls.push({ id: null, name: p.functionCall.name, args: p.functionCall.args || {} });
  }
  usage = {
    in: resp.usageMetadata?.promptTokenCount || 0,
    out: resp.usageMetadata?.candidatesTokenCount || 0
  };
}

return [{ json: { text: text.trim(), toolCalls, usage, provider, model: '__MODEL_NAME__', raw: resp } }];
